  ('5fdfd07e-bb6c-48f1-828b-1243d3e08376', $$Economie$$, $$VWO$$, $$Noorwegen leert van Nederland$$, $$VWO Economie 2022-III$$),
  ('c88c4745-6832-44d1-aee9-0330a3769838', $$Economie$$, $$VWO$$, $$Vasthouden aan de parto$$, $$VWO Economie 2022-III$$),
