insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('3225b7d0-cf90-439b-b7d5-98020046b040', '6a094b90-4e4f-4358-a70c-761248c2cb76', $$inleiding: Grasshoppers introduceert de insectenburger$$,
   $$economie-vwo-2022-iii-insectenburgers-niet-voor-de-poes-context1.png$$,
   $$In een land heeft het bedrijf Grasshoppers in samenwerking met een landbouwuniversiteit een ‘insectenburger’ ontwikkeld. Er is marktonderzoek verricht in het universiteitsrestaurant. Daaruit blijkt dat er een markt kan zijn voor insectenburgers. De onderneming besluit dan ook de insectenburgers te gaan produceren, maar streeft in het eerste jaar nog niet naar maximale totale winst. Voor de start van de productie gaat het management van Grasshoppers uit van de gegevens in tabel 1.$$, 'inline'),
  ('e7e492bc-785c-4b3d-bf98-9a075a077a35', '6a094b90-4e4f-4358-a70c-761248c2cb76', $$tabel 1: verwachte gegevens bij introductie van insectenburgers$$,
   $$economie-vwo-2022-iii-insectenburgers-niet-voor-de-poes-context2.png$$,
   $$tabel 1 verwachte gegevens bij introductie van insectenburgers
Qᵥ = -5.000P + 100.000 | Qᵥ = totale vraag insectenburgers in kilo’s; P = verkoopprijs in euro’s per kilo insectenburger
TVK = 2,5Q | totale variabele kosten van de productie (en afzet) van de insectenburgers in euro’s
TCKₗ = 140.000 | totale constante loonkosten in euro’s
TCKₒ = 260.000 | totale overige vaste kosten in euro’s (met name ontwikkelingskosten)
Toelichting: de vraagfunctie is afgeleid uit het gehouden marktonderzoek.$$, 'inline'),
  ('88c6ab7c-3783-4368-978b-ffcd19f572ba', '6a094b90-4e4f-4358-a70c-761248c2cb76', $$vleesburger als substituut; introductieprijs € 10; stelling over de autonome vraag$$,
   $$economie-vwo-2022-iii-insectenburgers-niet-voor-de-poes-context3.png$$,
   $$De huidige verkoopprijs per kilo voor een hamburger van vlees is € 7,50 en deze burger wordt gezien als een substituut van de insectenburger. Voor de insectenburger wordt een introductieprijs van € 10 per kilo gekozen. De onderzoeker beseft dat de vraagfunctie van insectenburgers slechts een schatting is van de werkelijke vraagfunctie van consumenten in het land: studenten die meededen aan het onderzoek zijn qua eetgewoonten en inkomen mogelijk niet representatief voor de Nederlandse bevolking. Hij stelt: “Hierdoor zou de waarde van de autonome vraag van 100.000 kilo zowel een onderschatting als een overschatting kunnen zijn.”$$, 'inline'),
  ('326b683f-809a-4330-8d2f-e5e50072fbeb', '6a094b90-4e4f-4358-a70c-761248c2cb76', $$verwacht verlies van € 25.000 bij de gekozen prijs$$,
   $$economie-vwo-2022-iii-insectenburgers-niet-voor-de-poes-context4.png$$,
   $$De gekozen prijs zal naar verwachting in het eerste productiejaar leiden tot een verlies van € 25.000. De directie heeft berekend dat bij elke andere verkoopprijs ook verlies zou zijn gedraaid.$$, 'inline'),
  ('3dd67646-6444-45ab-8c17-3eada896e127', '6a094b90-4e4f-4358-a70c-761248c2cb76', $$directie streeft in het eerste jaar naar maximale omzet$$,
   $$economie-vwo-2022-iii-insectenburgers-niet-voor-de-poes-context5.png$$,
   $$De directie besluit om in het eerste jaar niet te streven naar maximale winst, maar naar maximale omzet.$$, 'inline'),
  ('1c1f17b1-8003-45c7-b3c1-a9fb1dc9a4cf', '6a094b90-4e4f-4358-a70c-761248c2cb76', $$subsidievoorstel van € 1,75 per kilo bij een prijs van € 9; aspecten a t/m d$$,
   $$economie-vwo-2022-iii-insectenburgers-niet-voor-de-poes-context6.png$$,
   $$De overheid wil het op de markt brengen van insectenburgers door Grasshoppers steunen, met het oog op de maatschappelijke zorg over de milieuoverlast door vleesproductie. Er ligt een voorstel op tafel voor toekenning van een tijdelijke subsidie van € 1,75 per kilo als gedeeltelijke dekking van de variabele kosten, onder de voorwaarde dat de verkoopprijs van insectenburgers wordt verlaagd naar € 9 per kilo.
Vier aspecten worden in beschouwing genomen:
a de verwachte winstgevendheid van Grasshoppers
b de verwachte kosten van de subsidie, gegeven de verwachte vraag
c het bewaken van de concurrentie op de markt
d de wens van de overheid om negatieve externe effecten te beperken$$, 'inline'),
  ('b1f28e09-f882-4575-b1cd-2f784f2574b3', '6a094b90-4e4f-4358-a70c-761248c2cb76', $$ministerie van EZ tegen op basis van aspecten a en b$$,
   $$economie-vwo-2022-iii-insectenburgers-niet-voor-de-poes-context7.png$$,
   $$Het ministerie van Economische Zaken is op basis van aspecten a en b tegenstander van het subsidievoorstel.$$, 'inline'),
  ('fd78f7df-26b6-4a71-aaaa-66160caa0d09', '6a094b90-4e4f-4358-a70c-761248c2cb76', $$ministerie van Milieu vóór en EZ tegen op basis van aspecten c en d$$,
   $$economie-vwo-2022-iii-insectenburgers-niet-voor-de-poes-context8.png$$,
   $$Het ministerie van Milieu is op basis van aspecten c en d vóór het subsidievoorstel. Het ministerie van Economische Zaken is op basis van dezelfde aspecten tegen het subsidievoorstel.$$, 'inline'),
  ('5784670b-3f95-43c2-b2a6-4de01f789e56', '5fdfd07e-bb6c-48f1-828b-1243d3e08376', $$inleiding: Nederlandse gasbaten en de uitspraak van Van Zijl over werkloosheid$$,
   $$economie-vwo-2022-iii-noorwegen-leert-van-nederland-context1.png$$,
   $$In 1959 vond de Nederlandse Aardolie Maatschappij (NAM) een enorm aardgasveld in de Groningse bodem. Leidingen werden aangelegd zodat huishoudens van aardgas konden worden voorzien. Ook werden veel langlopende exportcontracten voor aardgas afgesloten. Hierdoor stroomde er veel geld in de Nederlandse schatkist waarmee de overheid een deel van haar lopende uitgaven financierde. Beleggingsexpert Van Zijl kijkt in het jaar 2017 terug op deze periode: “De jarenlange export van gas veroorzaakte, via de koers van de toenmalige gulden, werkloosheid.”$$, 'inline'),
  ('06f4f948-eef1-4d5e-933a-6cd7510e1448', '5fdfd07e-bb6c-48f1-828b-1243d3e08376', $$krantenartikel: het Noorse staatsfonds en zijn beleggingen in 2016$$,
   $$economie-vwo-2022-iii-noorwegen-leert-van-nederland-context2.png$$,
   $$Uit een krant (januari 2017):
Sinds de vondst van grote olie- en gasvelden onder de Noordzee is Noorwegen een belangrijke exporteur van olie en gas geworden. In de jaren negentig besloot de Noorse overheid haar inkomsten uit eigen verkoop van olie en gas, evenals de winstbelasting van de Noorse oliebedrijven, jaarlijks onder te brengen in een staatsfonds. Het fonds wordt voornamelijk in het buitenland belegd. De samenstelling van de beleggingen van het fonds was in 2016: 62,5% in aandelen; 3,2% in vastgoed en het overige deel in buitenlandse (staats)obligaties. In 2016 boekte het fonds een gemiddeld rendement van 8,7% op aandelen; 0,8% op vastgoedbeleggingen en 4,3% op buitenlandse (staats)obligaties. Het fonds dient voornamelijk om de komende lasten van vergrijzing op te vangen. Een wet bepaalt dat de Noorse overheid jaarlijks maximaal 4% aan het fonds mag onttrekken om haar lopende uitgaven te financieren.$$, 'inline'),
  ('1ef8f065-c03e-4ff3-9ef2-9f67f5d54bdf', '5fdfd07e-bb6c-48f1-828b-1243d3e08376', $$twee stellingen van Van Zijl over betalingsbalans en intertemporele afweging$$,
   $$economie-vwo-2022-iii-noorwegen-leert-van-nederland-context3.png$$,
   $$Van Zijl komt met twee stellingen op basis van dit artikel:
− De beleggingen van dit fonds zorgen ervoor dat de Noorse betalingsbalans niet te veel uit evenwicht raakt.
− De Noorse overheid en de Nederlandse overheid hebben voor de bestemming van de exportopbrengsten van gas (en olie) een verschillende intertemporele afweging gemaakt.$$, 'inline'),
  ('5c58862e-3677-4a76-a265-d3083d9e8476', '5fdfd07e-bb6c-48f1-828b-1243d3e08376', $$meer aandelen in het fonds vanaf 2017; portefeuille conjunctuurgevoeliger$$,
   $$economie-vwo-2022-iii-noorwegen-leert-van-nederland-context4.png$$,
   $$De Noorse regering heeft op advies van de Noorse Centrale Bank besloten om vanaf begin 2017 de beleggingen in aandelen op te schroeven naar 70% ten koste van obligaties. Van Zijl: “Dit lijkt verstandig aangezien de OESO (Organisatie voor Economische Samenwerking en Ontwikkeling) heeft becijferd dat de groei van de wereldeconomie in 2017 doorzet naar 3,5%, maar de beleggingsportefeuille is nu wel conjunctuurgevoeliger .…”$$, 'inline'),
  ('8843dc45-ff9a-4376-a678-07305b0a1e06', 'c88c4745-6832-44d1-aee9-0330a3769838', $$inleiding: begrotingsafspraken in de EMG; correctieve en preventieve arm$$,
   $$economie-vwo-2022-iii-vasthouden-aan-de-parto-context1.png$$,
   $$Om de stabiliteit van de gemeenschappelijke munt, de parto, te waarborgen hebben landen die deelnemen aan een Economische en Monetaire Gemeenschap (EMG) afspraken gemaakt over overheidsbegrotingen waaraan lidstaten moeten voldoen. Deze afspraken zijn opgesplitst in een zogenoemde correctieve arm en preventieve arm (deze zijn te zien in figuur 1 en gelden bij een laagconjunctuur).$$, 'inline'),
  ('960f2db2-a70b-4aef-b0e9-fe44e303223e', 'c88c4745-6832-44d1-aee9-0330a3769838', $$figuur 1: afspraken ten behoeve van stabiliteit van de parto$$,
   $$economie-vwo-2022-iii-vasthouden-aan-de-parto-context2.png$$,
   $$figuur 1 afspraken ten behoeve van stabiliteit van de parto
correctieve arm: lidstaten met financieringstekort > 2,5% van het bbp → regels voor begrotingsbeleid: • financieringstekort moet omlaag • anticyclisch begrotingsbeleid is niet toegestaan
preventieve arm: lidstaten met financieringstekort ≤ 2,5% van het bbp → regels voor begrotingsbeleid: • overheidsuitgaven mogen niet harder stijgen dan de economische groei. Een uitzondering geldt voor werkloosheidsuitkeringen • anticyclisch begrotingsbeleid beperkt toegestaan$$, 'inline'),
  ('beeb5946-4f15-4945-9e3d-0a4dd4d0000e', 'c88c4745-6832-44d1-aee9-0330a3769838', $$Drostland kampt met een hardnekkige laagconjunctuur$$,
   $$economie-vwo-2022-iii-vasthouden-aan-de-parto-context3.png$$,
   $$De economie van Drostland, een kleine lidstaat van de EMG, kampt met een hardnekkige laagconjunctuur (zie tabel 1).$$, 'inline'),
  ('4313ed87-7691-4e66-8e13-e43979463268', 'c88c4745-6832-44d1-aee9-0330a3769838', $$tabel 1: financieringstekort, staatsschuld en bbp in Drostland$$,
   $$economie-vwo-2022-iii-vasthouden-aan-de-parto-context4.png$$,
   $$tabel 1 financieringstekort, staatsschuld en bbp in Drostland
| 2010 | 2011 | 2012 | 2013 | 2014 | 2015 | 2016 | 2017
financieringstekort
- als % van het bbp | 3,5 | 3,4 | 3,3 | 3,1 | 3,1 | 3,1 | 3,0 | ....
- in miljard | 11,6 | 11,5 | 10,9 | 10,3 | 10,5 | 10,8 | 10,5 | 10,1
staatsschuld
- als % van het bbp | 59 | 61,4 | 66,4 | 68,7 | 70,1 | 72,6 | 75,2 | 76,8
- in miljard | 196 | 207,5 | 218,4 | 228,7 | 239,2 | 250,0 | 260,5 | 270,6
waarde bbp
- in miljard | 332 | 338 | 329 | 333 | 339 | 344 | 346 | ....$$, 'inline'),
  ('be34d7a8-58a0-4664-8bd1-7808656c5927', 'c88c4745-6832-44d1-aee9-0330a3769838', $$Drostland verlaat de EMG en voert de droste in; blijft in het GWM$$,
   $$economie-vwo-2022-iii-vasthouden-aan-de-parto-context5.png$$,
   $$De regering van Drostland wil zelf anticyclisch begrotingsbeleid (conjunctuurbeleid) kunnen voeren en besluit de EMG te verlaten. De parto is hiermee niet langer wettig betaalmiddel in het land en de droste wordt als munt ingevoerd. Drostland blijft wel deelnemen aan het Gemeenschappelijk Wisselkoers Mechanisme (GWM).$$, 'inline'),
  ('e582780b-9439-4bcf-9c32-4553d6b57db5', 'c88c4745-6832-44d1-aee9-0330a3769838', $$figuur 2: effect van conjunctuurbeleid op koersbepaling droste$$,
   $$economie-vwo-2022-iii-vasthouden-aan-de-parto-context6.png$$,
   $$figuur 2 effect van conjunctuurbeleid op koersbepaling droste
verticale as: koers droste in parto’s; horizontale as: Q (in miljarden drosten)
Lijnen: Qₐ = 250P - 200; Qₐ’ = 250P - 120 (stippellijn); Qᵥ = - 100P + 276
Op de verticale as zijn de koersen 1,636; 1,360 en 1,209 aangegeven; tussen 1,636 en 1,209 ligt de bandbreedte.
Qa = aangeboden hoeveelheid drosten
Qa’ = aangeboden hoeveelheid drosten na nieuw conjunctuurbeleid
Qv = gevraagde hoeveelheid drosten$$, 'inline'),
  ('5592c186-8b5a-4a2b-b1c6-9c0d0bab744d', 'c88c4745-6832-44d1-aee9-0330a3769838', $$spilkoers, interventiekoersen en bandbreedte in het GWM$$,
   $$economie-vwo-2022-iii-vasthouden-aan-de-parto-context7.png$$,
   $$Deelnemende landen aan het GWM koppelen hun valuta aan een spilkoers: een vaste waarde ten opzichte van de parto. De wisselkoers mag hier een vast gelijk percentage naar boven of naar beneden van afwijken. Dit zijn de bovenste en onderste interventiekoersen. Het verschil tussen deze koersen is de bandbreedte.$$, 'inline'),
  ('5bbcfe0d-e92b-43ce-87f2-3574c5ffd823', 'c88c4745-6832-44d1-aee9-0330a3769838', $$belastingverlaging leidt tot koersdaling; CB kiest voor steunaankopen$$,
   $$economie-vwo-2022-iii-vasthouden-aan-de-parto-context8.png$$,
   $$De overheid van Drostland kan nu zelfstandig conjunctuurbeleid voeren en besluit de tarieven van de inkomstenbelasting te verlagen. Dit leidt via de lopende rekening van de betalingsbalans tot een daling van de koers van de droste (zie figuur 2). Om te voorkomen dat de koers onder de bandbreedte daalt, kan de Centrale Bank (CB) van het land kiezen tussen een renteaanpassing of steunaankopen op de valutamarkt. Zij kiest voor het laatste.$$, 'inline'),
  ('0c58a27f-0e33-48a0-924b-c4504ace6310', '4cd391d5-19e5-4abe-8abc-ee97755616f2', $$inleiding: beleggingsadviseur Hans gebruikt de conjunctuurklok$$,
   $$economie-vwo-2022-iii-wijzer-van-de-conjunctuurklok-context1.png$$,
   $$Hans is beleggingsadviseur bij een bank. Hij gebruikt een aangepaste versie van de conjunctuurklok (figuur 1) om de stand en het verloop van de economie te voorspellen. Hiermee kan hij inschatten hoe bijvoorbeeld aandelenkoersen zich zullen ontwikkelen en kan hij zijn beleggingsadviezen onderbouwen. Deze conjunctuurklok is samengesteld door een statistisch bureau en laat van een aantal indicatoren zien of deze duiden op een opgang of neergang van de conjunctuur. De symbolen staan op de plaats die de positie van de indicator in het laatste kwartaal van 2017 aangeeft.$$, 'inline'),
  ('8e33a54c-133c-4a10-8040-2c865c9f6c73', '4cd391d5-19e5-4abe-8abc-ee97755616f2', $$schaalverdeling van de assen$$,
   $$economie-vwo-2022-iii-wijzer-van-de-conjunctuurklok-context2.png$$,
   $$De schaalverdeling op de assen geldt alleen voor de verandering van het reële bbp, de uitvoer en de reële investeringen. Voor consumentenvertrouwen en werkloosheid geldt een afwijkende schaal.$$, 'inline'),
  ('6cfe96c6-d60b-4017-b0e9-b79982c1febe', '4cd391d5-19e5-4abe-8abc-ee97755616f2', $$consumentenvertrouwen: hoogconjunctuur maar afgenomen$$,
   $$economie-vwo-2022-iii-wijzer-van-de-conjunctuurklok-context3.png$$,
   $$Zo geldt voor het consumentenvertrouwen dat dit zich in een hoogconjunctuur bevindt, maar wel is afgenomen ten opzichte van het vorige kwartaal.$$, 'inline'),
  ('c2da1fb3-cf59-4ad6-90ab-5f8f7dd96719', '4cd391d5-19e5-4abe-8abc-ee97755616f2', $$figuur 1: conjunctuurklok van kwartaal 4 (2017), met toelichting$$,
   $$economie-vwo-2022-iii-wijzer-van-de-conjunctuurklok-context4.png$$,
   $$figuur 1 conjunctuurklok van kwartaal 4 (2017)
verticale as: boven/onder de trend (in procentpunt), van -0,4 tot 0,4; horizontale as: afname/toename groei t.o.v. vorig kwartaal in procentpunten, van -0,4 tot 0,4
De symbolen staan op de plaats die de positie van de indicator in het laatste kwartaal van 2017 aangeeft (zie de afbeelding).
Legenda:
□ = procentuele stijging van het reële bbp ten opzichte van het voorafgaande kwartaal
☆ = procentuele stijging van de reële investeringen door bedrijven.
○ = consumentenvertrouwen
△ = werkloosheid
◇ = uitvoer
Toelichting: de trendmatige ontwikkeling van het bbp is 0,3% reële groei per kwartaal.$$, 'inline'),
  ('e7ffa302-59c4-4f73-b289-9c07802887e3', '4cd391d5-19e5-4abe-8abc-ee97755616f2', $$werkloosheid als achterlopende indicator$$,
   $$economie-vwo-2022-iii-wijzer-van-de-conjunctuurklok-context5.png$$,
   $$Hans leest in een toelichting op de conjunctuurklok dat de werkloosheid een achterlopende indicator is. De werkloosheid begint pas af te nemen als er al enige tijd een opgaande conjunctuur is.$$, 'inline'),
  ('c94a2382-433e-482c-8f86-947fa5d1ce89', '4cd391d5-19e5-4abe-8abc-ee97755616f2', $$verwachting van Hans over de investeringen in 2018$$,
   $$economie-vwo-2022-iii-wijzer-van-de-conjunctuurklok-context6.png$$,
   $$Hans verwacht dat de investeringen van bedrijven in het eerste kwartaal van 2018 in het kwadrant rechtsboven zullen liggen. Hij baseert deze verwachting op een andere indicator in de conjunctuurklok.$$, 'inline'),
  ('b443ba1f-5af6-4d9e-8c99-47a793cc891e', '4cd391d5-19e5-4abe-8abc-ee97755616f2', $$voorspelling van Hans over de aandelenkoersen in 2018$$,
   $$economie-vwo-2022-iii-wijzer-van-de-conjunctuurklok-context7.png$$,
   $$Ondanks de hoogconjunctuur is Hans voorzichtig in zijn voorspellingen over de aandelenkoersen. Op basis van zijn analyse van de conjunctuurklok over het laatste kwartaal van 2017 voorspelt Hans een mogelijke daling van de aandelenkoersen in 2018 tegen de achtergrond van de ontwikkeling van het consumentenvertrouwen.$$, 'inline'),
  ('e0a5b46d-e492-410f-9b3e-a189061259f8', 'f54ccda6-7107-4952-8c7c-d7d54fd580e0', $$inleiding: arbeidsongeschiktheid en vergrijzing bedreigen het omslagstelsel$$,
   $$economie-vwo-2022-iii-activerend-arbeidsmarktbeleid-context1.png$$,
   $$In een land brengen de toegenomen arbeidsongeschiktheid en de stijgende vergrijzing de financiering van de sociale verzekeringen, waarbij het omslagstelsel wordt toegepast, in gevaar. De minister van Sociale Zaken analyseert de situatie en gebruikt daarbij onder andere tabel 1.$$, 'inline'),
  ('48c29924-8298-49fb-9319-842a1c68e92c', 'f54ccda6-7107-4952-8c7c-d7d54fd580e0', $$tabel 1: verhouding tussen inactieven en actieven, 2009-2018$$,
   $$economie-vwo-2022-iii-activerend-arbeidsmarktbeleid-context2.png$$,
   $$tabel 1 verhouding tussen inactieven en actieven, 2009 - 2018
2009 | 2010 | 2011 | 2012 | 2013 | 2014 | 2015 | 2016 | 2017 | 2018
0,670 | 0,654 | 0,630 | 0,6450 | 0,649 | 0,631 | 0,629 | 0,620 | 0,618 | 0,616$$, 'inline'),
  ('ed8710ac-4ff5-42d8-abf1-41f47cd7a97c', 'f54ccda6-7107-4952-8c7c-d7d54fd580e0', $$definitie inactieven, actieven en i/a-ratio$$,
   $$economie-vwo-2022-iii-activerend-arbeidsmarktbeleid-context3.png$$,
   $$Onder inactieven worden uitkeringsgerechtigden verstaan (bijvoorbeeld voor werkloosheid, staatspensioen, bijstand). Onder actieven worden de werkenden verstaan. Een i/a-ratio (inactieven/actieven) van 0,5 betekent dat voor iedere inactieve er twee actieven staan.$$, 'inline'),
  ('1772e1d3-8281-42de-97a8-7db8d64ed9b7', 'f54ccda6-7107-4952-8c7c-d7d54fd580e0', $$conclusies a, b en c van de minister$$,
   $$economie-vwo-2022-iii-activerend-arbeidsmarktbeleid-context4.png$$,
   $$De minister van Sociale Zaken concludeert op basis van de tabel dat:
a de regering zich moet inzetten om de participatiegraad te laten stijgen, met als gevolg dat de i/a-ratio verder omlaag kan;
b als het niet lukt om de i/a-ratio te laten dalen, toekomstige regeringen steeds meer moeite zullen krijgen om bij vergrijzing de financiering van het staatspensioen rond te krijgen. Hierdoor ontstaat een grotere druk op de solidariteit binnen en tussen generaties.
c indien het niet lukt om de i/a-ratio verder te verlagen, de pensioenleeftijd verder zal worden verhoogd.$$, 'inline'),
  ('5413a62d-cdc8-4cf6-ad48-0cb3ed393245', 'f54ccda6-7107-4952-8c7c-d7d54fd580e0', $$voorstel aanpassing Wet inkomstenbelasting om doelgroepen te activeren$$,
   $$economie-vwo-2022-iii-activerend-arbeidsmarktbeleid-context5.png$$,
   $$De minister van Sociale Zaken stelt een aanpassing voor van de Wet inkomstenbelasting met als doel om meer doelgroepen zoals werklozen en bijstandsgerechtigden te stimuleren de arbeidsmarkt te betreden. De voorgestelde aanpassing staat in tabel 2.$$, 'inline'),
  ('a5a22383-24bd-4292-bc30-6b0d041a0eb0', 'f54ccda6-7107-4952-8c7c-d7d54fd580e0', $$tabel 2: oud en nieuw stelsel van inkomstenbelasting$$,
   $$economie-vwo-2022-iii-activerend-arbeidsmarktbeleid-context6.png$$,
   $$tabel 2 oud en nieuw stelsel van inkomstenbelasting
oud stelsel inkomstenbelasting (2018): schijven | tarief
€ 0 - 12.000 | 37%
€ 12.001 - 37.000 | 41%
€ 37.001 - 67.000 | 42%
> € 67.000 | 52%
arbeidskorting: € 1.000 per persoon per jaar
nieuw stelsel inkomstenbelasting (ingaande 2019): schijven | tarief
€ 0 - 20.000 | 35%
€ 20.001 - 70.000 | 40%
> € 70.000 | 50%
arbeidskorting: Voor mensen met een arbeidsinkomen tot maximaal € 15.000 per jaar is de arbeidskorting € 1.500. Voor mensen met een arbeidsinkomen vanaf € 15.000 per jaar wordt deze korting verminderd met € 40 per € 1.000 extra jaarinkomen.$$, 'inline'),
  ('8d5c3dad-6648-42be-9da8-6ab6c6fc9c6f', 'f54ccda6-7107-4952-8c7c-d7d54fd580e0', $$gevolgen voor actieven; modaal belastbaar arbeidsinkomen € 38.500$$,
   $$economie-vwo-2022-iii-activerend-arbeidsmarktbeleid-context7.png$$,
   $$De voorgestelde verandering van de wet inkomstenbelasting heeft niet alleen gevolgen voor de groep inactieven. De minister van Sociale Zaken wil ook weten wat de gevolgen zijn voor de huidige actieven. Hij verwacht namelijk dat de actieven zich hierdoor minder zullen aanbieden op de arbeidsmarkt. In het land geldt dat het modale belastbaar arbeidsinkomen € 38.500 is per jaar.$$, 'inline'),
  ('dc780f59-b35f-4f1d-b4f4-1cbeb2dfe74d', 'd9be6a67-fb5b-4c97-9f5c-71ebfa9145f6', $$inleiding: bankfaillissementen, vertrouwenscrisis en recessie; staatsschuld en overheidstekort$$,
   $$economie-vwo-2022-iii-monetair-geschut-tegen-de-recessie-context1.png$$,
   $$In een land zijn in 2014 enkele banken failliet gegaan. De overheid heeft grote banken nog nét kunnen redden. Ondanks de aanvulling van het eigen vermogen hadden die banken onvoldoende dekkingsmiddelen op hun balansen. De banksector kreeg te maken met een vertrouwenscrisis, die mede de aanleiding was voor een recessie in de jaren 2014 en 2015. De staatsschuldquote bedroeg op 1 januari 2015 100% van het bruto binnenlands product (bbp). Over het jaar 2015 was het overheidstekort opgelopen tot 6% van het bbp. Voor de jaren 2014 en 2015 zijn de waarden van enkele macro-economische grootheden gepresenteerd in tabel 1.$$, 'inline'),
  ('bca28b69-afff-4ecb-b2eb-6d725d6980e9', 'd9be6a67-fb5b-4c97-9f5c-71ebfa9145f6', $$tabel 1: macro-economische gegevens tijdens de recessie$$,
   $$economie-vwo-2022-iii-monetair-geschut-tegen-de-recessie-context2.png$$,
   $$tabel 1 macro-economische gegevens tijdens de recessie
variabele | 2014 | 2015
maatschappelijke geldhoeveelheid (M) | € 81 miljard | € 82 miljard
nationaal inkomen | € 500 miljard | € 505,5 miljard$$, 'inline'),
  ('ed511c5f-3de7-4340-9cc9-1d59f3e29a0d', 'd9be6a67-fb5b-4c97-9f5c-71ebfa9145f6', $$verkeersvergelijking van Fisher en verklaring van de symbolen$$,
   $$economie-vwo-2022-iii-monetair-geschut-tegen-de-recessie-context3.png$$,
   $$Bij de analyses ging een econoom uit van de verkeersvergelijking van Fisher: M × V = P × T.
Voor de symbolen geldt:
M = geldhoeveelheid in handen van het publiek
V = de gemiddelde omloopsnelheid van het geld
P = het gemiddelde prijsniveau van de transacties
T = het aantal transacties$$, 'inline'),
  ('a3e573b9-80f0-40d2-b672-eba8f6e31b73', 'd9be6a67-fb5b-4c97-9f5c-71ebfa9145f6', $$Centrale Bank voert vanaf 2015 een ruimgeldpolitiek$$,
   $$economie-vwo-2022-iii-monetair-geschut-tegen-de-recessie-context4.png$$,
   $$In 2015 heeft de directie van de Centrale Bank besloten om in de jaren die volgen de geldhoeveelheid sterk te verhogen. Dit wordt ook wel aangeduid als een ‘ruimgeldpolitiek’.$$, 'inline');

