   $$economie-vwo-2022-iii-vasthouden-aan-de-parto-vraag14.png$$, $$2p 14 Leg uit dat het gevoerde conjunctuurbeleid heeft geleid tot een koersdaling van de droste.$$, array['e582780b-9439-4bcf-9c32-4553d6b57db5', '5bbcfe0d-e92b-43ce-87f2-3574c5ffd823']::uuid[]),
