   $$economie-vwo-2022-iii-vasthouden-aan-de-parto-vraag16.png$$, $$2p 16 Bereken het minimale bedrag in parto’s van de benodigde steunaankopen door de CB van Drostland op de valutamarkt.$$, array['e582780b-9439-4bcf-9c32-4553d6b57db5', '5592c186-8b5a-4a2b-b1c6-9c0d0bab744d', '5bbcfe0d-e92b-43ce-87f2-3574c5ffd823']::uuid[]),
