   $$economie-vwo-2022-iii-wijzer-van-de-conjunctuurklok-vraag17.png$$, $$2p 17 Leg uit waarom de werkloosheid een achterlopende indicator is.$$, array['0c58a27f-0e33-48a0-924b-c4504ace6310', '8e33a54c-133c-4a10-8040-2c865c9f6c73', '6cfe96c6-d60b-4017-b0e9-b79982c1febe', 'c2da1fb3-cf59-4ad6-90ab-5f8f7dd96719', 'e7ffa302-59c4-4f73-b289-9c07802887e3']::uuid[]),
